/**
 *  A single step inside a job - the level ADO's log view shows, and the
 *  level a failure is actually pinned to.
 */
export type TimelineTask = {
	name: string,
	/**  "completed" | "inProgress" | "pending". */
	state: string,
	/**  "succeeded" | "failed" | "skipped" | "abandoned" | "" while running. */
	result: string,
	started: string,
	finished: string,
	/**
	 *  Error/warning text ADO attached to this step - the summary you get
	 *  without fetching anything.
	 */
	issues: string[],
	/**
	 *  Timeline log id, when this step produced output. 0 = none yet (a
	 *  pending step, or one whose logs have been cleaned up).
	 */
	log_id: number,
};

/**
 *  Emitted while an update package downloads, so the banner can show a bar
 *  instead of a spinner that says nothing about how long is left.
 * 
 *  `total` is exact - the size the release feed gives. `downloaded` is that
 *  share of it implied by `percent`, which Velopack floors to the nearest
 *  5%, so it steps rather than counts. Bytes are f64 because u64 is not
 *  exportable over these bindings; an installer is nowhere near the limit
 *  where a double stops being exact.
 */
export type UpdateProgress = {
	percent: number,
	downloaded: number | null,
	total: number | null,
};

/**
 *  The outcome of an update check - all THREE of them.
 * 
 *  This used to be an Option, so "a newer version exists", "you are up to
 *  date", "this build cannot update itself" and "the feed was unreachable"
 *  collapsed into two answers. The app told the last two "You are on the
 *  latest version", which is a claim it had not checked and could not make.
 */
export type UpdateStatus = {
	/**  The newer version, when there is one. */
	available: string | null,
	/**
	 *  Why no check happened. When this is set, `available` being None
	 *  means "unknown", NOT "up to date".
	 */
	blocked: string | null,
	/**
	 *  A version a previous "Restart to update" tried and failed to reach.
	 * 
	 *  The apply happens after this process has exited, so the only way
	 *  the app can know it failed is forensically: `note_attempt` records
	 *  the target version just before the hand-off, and the next launch
	 *  finds itself still on the old version. Without this the failure is
	 *  invisible - the app restarts, the banner comes back, and the user
	 *  is left to wonder whether clicking it did anything at all.
	 */
	failed_attempt: string | null,
};

/**
 *  Emitted when the JSON file an import is following changes on disk -
 *  once per real content change, never on a save that rewrote the same
 *  bytes. `stamp` is the new fingerprint (see filewatch.rs).
 */
export type WatchedFileChanged = {
	path: string,
	stamp: string,
};

